import{_ as e,o as a,c as o,a4 as s}from"./chunks/framework.BabNWGMA.js";const u=JSON.parse('{"title":"📐 线性代数 知识点笔记","description":"","frontmatter":{},"headers":[],"relativePath":"subjects/线性代数.md","filePath":"subjects/线性代数.md","lastUpdated":1789102210000}'),r={name:"subjects/线性代数.md"};function n(c,t,l,p,_,d){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="📐-线性代数-知识点笔记" tabindex="-1">📐 线性代数 知识点笔记 <a class="header-anchor" href="#📐-线性代数-知识点笔记" aria-label="Permalink to &quot;📐 线性代数 知识点笔记&quot;">​</a></h1><blockquote><p>共 <strong>1</strong> 个知识点 · 隔天自动更新</p></blockquote><h2 id="行列式的定义与基本性质" tabindex="-1">行列式的定义与基本性质 <a class="header-anchor" href="#行列式的定义与基本性质" aria-label="Permalink to &quot;行列式的定义与基本性质&quot;">​</a></h2><blockquote><p><strong>掌握度:</strong> 50% | <strong>创建:</strong> 2026-09-15 | <strong>最近复习:</strong> 2026-09-15</p></blockquote><blockquote><p>掌握度进度: █████░░░░░</p></blockquote><p><strong>核心内容:</strong></p><p>行列式=按固定规则把 n×n 个数算成的一个数(不是矩阵)。2阶:|a b; c d| = ad-bc。3阶:对角线法则(沙路法)——主对角线三乘积之和 减 副对角线三乘积之和;更高阶:按某一行(列)展开,元素×代数余子式再求和。高频性质:①交换两行(列),值变号;②某行(列)全部乘 k,值乘 k(故可提公因子);③两行相同或成比例,值为 0;④某行乘 k 加到另一行,值不变(化简主力,把行列式化上三角再对角相乘)。考察方式:数值计算、含参行列式、用性质判 0、与方程组/特征值联动。</p><details class="example-box"><summary>💡 点击展示例题答案</summary><p>例:求 |2 1; 3 4|。解:=2×4-1×3=5。验算性质①:交换两行得 |3 4; 2 1| = 3×1-4×2 = -5,恰为原值变号,性质①成立。再例:|1 2 3; 4 5 6; 7 8 9|:因第1行+第3行=(8,10,12)=2×第2行,三行线性相关 → 值为 0(性质③)。</p></details><hr>',9)])])}const b=e(r,[["render",n]]);export{u as __pageData,b as default};
